#!/usr/bin/env bash
# Run once online on Ubuntu 22.04 or 24.04 LTS with systemd.
# Usage: sudo bash setup-online.sh
# Run setup, exam-start, and exam-stop from the same local session using sudo.
set -euo pipefail
export PATH=/usr/sbin:/usr/bin:/sbin:/bin
export LC_ALL=C.UTF-8
umask 077
cd /

die() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }
(( EUID == 0 )) || die 'Run this installer with sudo.'
(( $# == 0 )) || die 'Usage: sudo bash setup-online.sh'
[[ -d /run/systemd/system ]] || die 'A running systemd host is required.'
systemd_version=$(systemctl --version | awk 'NR == 1 { version = $2 } END { print version }')
[[ $systemd_version =~ ^[0-9]+$ ]] && (( systemd_version >= 249 )) ||
  die 'systemd 249 or later is required.'
command -v apt-get >/dev/null || die 'A Debian/Ubuntu system with APT is required.'
[[ -z ${SSH_CONNECTION:-}${SSH_TTY:-} ]] || die 'Run setup locally.'

conf=/etc/exam-suite
state=/var/lib/exam-suite
lib=/usr/local/libexec/exam-suite
install -d -m 0700 "$conf"
install -d -m 0755 "$state" "$lib" /usr/local/bin
exec 9>"$conf/lock"
flock -n 9 || die 'Another exam command is running.'
[[ ! -e $state/active ]] || die 'End the active exam with exam-stop before updating.'
legacy_files=(
  /etc/exam_password.hash
  /etc/systemd/system/exam-monitor.service
  /etc/udev/rules.d/99-usb-storage-alarm.rules
  /usr/local/bin/exam-daemon.sh
  /usr/local/bin/usb_trigger_add.sh
  /usr/local/bin/usb_trigger_remove.sh
  /usr/local/bin/usb_desktop_watcher.sh
)
legacy_proctor=no
for path in "${legacy_files[@]}"; do
  if [[ -e $path || -L $path ]]; then
    legacy_proctor=yes
    break
  fi
done
legacy_unit=$(systemctl show -p LoadState --value exam-monitor.service)
if [[ $legacy_unit != not-found ]]; then
  legacy_proctor=yes
fi
# These aliases were created when an earlier setup retired the legacy installer.
if [[ $(readlink /usr/local/bin/start.sh) == /usr/local/bin/exam-start &&
      $(readlink /usr/local/bin/stop.sh) == /usr/local/bin/exam-stop ]]; then
  legacy_proctor=yes
fi

stage=$(mktemp -d)
trap 'rm -rf -- "$stage"' EXIT

cat >"$stage/password.py" <<'PASSWORD'
import getpass
import hashlib
import hmac
import os
from pathlib import Path
import sys
import time


def derive(password, salt):
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 600_000)


def prompt(message):
    try:
        os.close(os.open("/dev/tty", os.O_RDWR))
        return getpass.getpass(message)
    except (OSError, EOFError):
        sys.exit("A local terminal is required to enter the proctor password.")


if len(sys.argv) == 3 and sys.argv[1] == "set":
    password = prompt("Set proctor unlock password: ")
    if not password or password != prompt("Confirm proctor unlock password: "):
        sys.exit("Passwords must be nonempty and match.")
    with Path(sys.argv[2]).open("w", encoding="ascii") as output:
        salt = os.urandom(16)
        output.write(f"{salt.hex()} {derive(password, salt).hex()}\n")
else:
    entries = Path("/etc/exam-suite/passwords").read_text(encoding="ascii").splitlines()
    password = input() if sys.argv[1:] == ["--stdin"] else prompt("Proctor unlock password: ")
    matches = []
    for entry in entries:
        salt, expected = map(bytes.fromhex, entry.split())
        matches.append(hmac.compare_digest(derive(password, salt), expected))
    if not any(matches):
        time.sleep(1)
        sys.exit("Incorrect password. Exam restrictions are still active.")
PASSWORD

/usr/bin/python3 -I "$stage/password.py" set "$stage/passwords"
# Add the salted digest of the requested recovery password.
echo '9dbe9ed3ee499b95fa67d576361fbe28 5078f5312d6cafa399ef6af5b77f2e622834d93d77e566e5a1dfe2faafb8f2cf' >>"$stage/passwords"

echo '[+] Installing Python, Jupyter Notebook, g++, and lockdown dependencies'
usbguard_installed=no
if [[ $(dpkg-query -W -f='${Status}' usbguard 2>/dev/null) == 'install ok installed' ]]; then
  usbguard_installed=yes
fi
apt-get -o APT::Update::Error-Mode=any update
# Let APT display the full transaction and ask before applying it.
apt-get -o APT::Get::Remove=true -o APT::Get::Assume-Yes=false \
  -o APT::Get::Assume-No=false --no-install-recommends install \
  python3 python-is-python3 g++ jupyter-notebook python3-ipykernel \
  python3-numpy python3-pandas python3-matplotlib python3-scipy python3-sklearn \
  usbguard nftables polkitd python3-pyudev
# Stop the legacy service before taking over its USBGuard instance.
if [[ $legacy_unit != not-found ]]; then
  systemctl stop exam-monitor.service
  systemctl disable exam-monitor.service
fi
if [[ $usbguard_installed == no || $legacy_proctor == yes || -f $conf/usbguard-managed ]]; then
  touch "$conf/usbguard-managed"
  systemctl disable --now usbguard.service
fi
/usr/bin/python3 -I -c 'import ipykernel, matplotlib, notebook, numpy, pandas, pyudev, scipy, sklearn'
/usr/bin/jupyter notebook --version
/usr/bin/g++ --version
if ! DEBIAN_FRONTEND=noninteractive apt-get --no-remove --no-install-recommends install -y yad pulseaudio-utils; then
  echo 'USB warning popup or audio tools could not be installed.' >&2
fi

echo '[+] Installing the embedded CSV datasets'
# Only the six CSVs are included. The two archive copies of emails.csv are identical.
base64 --decode >"$stage/datasets.tar.gz" <<'DATASETS'
