cat >"$stage/home.py" <<'HOME'
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile

command, *args = sys.argv[1:]


def logged_in_uid():
    sessions = subprocess.check_output(
        ["/usr/bin/loginctl", "list-sessions", "--no-legend", "--no-pager"],
        text=True,
    )
    desktops = set()
    consoles = set()
    for line in sessions.splitlines():
        fields = line.split()
        if not fields:
            continue
        details = subprocess.run(
            ["/usr/bin/loginctl", "show-session", fields[0], "--no-pager",
             "-p", "User", "-p", "Remote", "-p", "Type", "-p", "Class", "-p", "State"],
            capture_output=True, text=True,
        )
        if details.returncode:
            continue
        props = dict(row.split("=", 1) for row in details.stdout.splitlines() if "=" in row)
        uid = props.get("User", "")
        if (
            props.get("Remote") != "no"
            or props.get("Class") not in {"user", "user-early"}
            or props.get("State") not in {"active", "online"}
            or not uid.isdecimal() or int(uid) < 1000
        ):
            continue
        if props.get("Type") in {"wayland", "x11"}:
            desktops.add(uid)
        elif props.get("Type") == "tty":
            consoles.add(uid)

    caller = os.environ.get("SUDO_UID")
    if caller and caller != "0":
        if caller in desktops or caller in consoles:
            return caller
        sys.exit("Run exam-start from the logged-in local session you want to use.")

    candidates = desktops or consoles
    if len(candidates) != 1:
        sys.exit("Exam start requires exactly one identifiable local desktop or console user.")
    return candidates.pop()


if command == "detect":
    print(logged_in_uid())
    sys.exit(0)

if command == "polkit-pkla":
    user = args[0]
    if any(character in user for character in "\n\r;*?[]"):
        sys.exit("Unsupported username for the local PolicyKit rule.")
    print(f"""[Exam suite]
Identity=unix-user:{user}
Action=*
ResultAny=no
ResultInactive=no
ResultActive=no""")
    sys.exit(0)

if command == "polkit":
    import json

    print(f"""polkit.addRule(function(action, subject) {{
    if (subject.user === {json.dumps(args[0])}) {{
        return polkit.Result.NO;
    }}
}});""")
    sys.exit(0)

if command == "check-usb":
    import json

    disks = json.loads(subprocess.check_output(
        ["/usr/bin/lsblk", "--json", "--output", "NAME,TRAN,MOUNTPOINTS"],
        text=True,
    ))

    def mounted_usb(devices, parent_is_usb=False):
        for device in devices:
            is_usb = parent_is_usb or device["tran"] == "usb"
            if is_usb and any(device["mountpoints"] or []):
                sys.exit(f"Unmount USB storage {device['name']} before starting exam mode.")
            mounted_usb(device.get("children", []), is_usb)

    mounted_usb(disks["blockdevices"])
elif command == "check-mounts":
    home = Path(args[0])
    # mountinfo includes same-filesystem bind mounts, which find -xdev cannot detect.
    for line in Path("/proc/self/mountinfo").read_text().splitlines():
        raw = line.split(" ")[4]
        mount = Path(re.sub(r"\\([0-7]{3})", lambda m: chr(int(m[1], 8)), raw))
        if mount == home or home in mount.parents:
            sys.exit(f"Unmount {mount} before wiping {home}.")
elif command == "seed":
    home = Path(args[0])
    # This branch runs as the detected user. Existing files and symlinks are preserved.
    for source in sorted(Path("/var/lib/exam-suite/datasets").glob("*.csv")):
        dest = home / source.name
        if os.path.lexists(dest):
            print(f"Kept existing {dest.name}")
            continue
        with tempfile.NamedTemporaryFile(dir=home, prefix=".exam-dataset-") as output:
            with source.open("rb") as input_file:
                shutil.copyfileobj(input_file, output)
            output.flush()
            try:
                os.link(output.name, dest)
            except FileExistsError:
                print(f"Kept existing {dest.name}")
else:
    sys.exit(f"Unknown exam helper command: {command}")
HOME
install -m 0755 "$stage/home.py" "$lib/home.py"

cat >"$stage/control" <<'CONTROL'
#!/usr/bin/env bash
set -euo pipefail
export PATH=/usr/sbin:/usr/bin:/sbin:/bin
export LC_ALL=C.UTF-8
umask 077
cd /

die() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }
conf=/etc/exam-suite
state=/var/lib/exam-suite
lib=/usr/local/libexec/exam-suite
alert=$state/usb-storage
dropin=/etc/systemd/system/usbguard.service.d/90-exam-suite.conf
polkit_rule=/etc/polkit-1/rules.d/00-00-exam-suite.rules
polkit_pkla=/etc/polkit-1/localauthority/90-mandatory.d/00-exam-suite.pkla

check_exam_user() {
  local entry parent_mode
  exam_uid=$(/usr/bin/python3 -I "$lib/home.py" detect) || exit 1
  entry=$(getent passwd "$exam_uid") || die 'The logged-in account no longer exists.'
  IFS=: read -r exam_user _ _ _ _ home _ <<<"$entry"
  [[ $home == /home/* && ${home#/home/} != */* && -d $home &&
     $(realpath -e -- "$home") == "$home" ]] ||
    die 'The logged-in user must have a real home directory directly under /home.'
  parent_mode=$(stat -c '%a' /home)
  [[ $(stat -c '%u' /home) == 0 ]] && (( (8#$parent_mode & 0022) == 0 )) ||
    die '/home must be root-owned and writable only by root.'
  [[ $(stat -c '%u' -- "$home") == "$exam_uid" ]] ||
    die 'The logged-in user must own their home directory.'
}

restore_usb_defaults() {
  local setting
  for setting in /sys/bus/usb/devices/usb*/authorized_default; do
    [[ -f $setting ]] || continue
    # An inactive daemon may have left exam-era defaults behind.
    if ! printf '1\n' >"$setting"; then
      [[ ! -e $setting ]] || return 1
    fi
  done
}

restore() {
  local previous=${1:-}
  if [[ -f $conf/usbguard-managed ]]; then
    previous=inactive
  elif [[ -z $previous ]]; then
    if [[ -f $state/active ]]; then
      read -r previous <"$state/active" || return
    elif [[ -f $state/.active.next ]]; then
      read -r previous <"$state/.active.next" || return
    elif [[ ! -e $dropin ]] && systemctl is-active --quiet usbguard.service; then
      # A running USBGuard instance without the exam override manages its own policy.
      previous=keep
    else
      previous=inactive
    fi
  fi
  # Remove the Upholds dependency before touching USBGuard.
  systemctl stop exam-lockdown.service exam-usb-alert.service || return
  rm -f -- "$dropin" || return
  systemctl daemon-reload || return
  case "$previous" in
    active)
      systemctl restart usbguard.service || return
      ;;
    inactive)
      systemctl stop usbguard.service || return
      restore_usb_defaults || return
      /usr/bin/python3 -I "$lib/usb-monitor" --restore-storage || return
      ;;
    keep)
      ;;
    *)
      echo 'Could not determine the previous USBGuard state.' >&2
      return 1
      ;;
  esac
  rm -f -- "$polkit_rule" "$polkit_pkla" || return
  if nft list table inet exam_suite >/dev/null 2>&1; then
    nft delete table inet exam_suite || return
  fi
  rm -f -- "$alert" "$state/active" "$state/.active.next" || return
  sync -f "$state"
}

(( EUID == 0 )) || die "Run ${0##*/} with sudo from the administrator account."
[[ -z ${SSH_CONNECTION:-}${SSH_TTY:-} ]] || die 'Run this command locally.'
if [[ ${0##*/} == exam-clear-alert ]]; then
  case "$#:${1:-}" in
    0:) ;;
    1:--stdin)
      # Read before locking so an idle popup cannot block other exam commands.
      IFS= read -rs -t 3 -n 4097 attempt && (( ${#attempt} <= 4096 )) ||
        die 'Could not read the proctor password.'
      ;;
    *) die 'Usage: sudo exam-clear-alert' ;;
  esac
fi
exec 9>"$conf/lock"
flock -n 9 || die 'Another exam command is running.'

case "${0##*/}" in
  exam-clear-alert)
    [[ -f $state/active && -f $alert ]] || exit 0
    if [[ ${1:-} == --stdin ]]; then
      printf '%s\n' "$attempt" | /usr/bin/python3 -I "$lib/password.py" --stdin
    else
      /usr/bin/python3 -I "$lib/password.py"
    fi
    rm -f -- "$alert"
    sync -f "$state"
    ;;
  exam-stop|stop.sh)
    (( $# == 0 )) || die 'Usage: sudo exam-stop'
    /usr/bin/python3 -I "$lib/password.py"
    restore || die 'Restoration was incomplete. Check the error and retry exam-stop.'
    echo 'Exam mode is off.'
    ;;
  exam-start|start.sh)
    wipe=no
    case "$#:${1:-}" in
      0:|1:--no-wipe) ;;
      1:--wipe) wipe=yes ;;
      *) die 'Usage: sudo exam-start [--wipe | --no-wipe]' ;;
    esac
    if [[ -f $state/active ]]; then
      die 'Exam mode is already active. End it with exam-stop before starting again.'
    fi
    check_exam_user
    /usr/bin/python3 -I "$lib/home.py" check-usb
    if [[ $wipe == yes ]]; then
      /usr/bin/python3 -I "$lib/home.py" check-mounts "$home"
    fi
    nft --check --file "$conf/firewall.nft"

    previous=inactive
    if systemctl is-active --quiet usbguard.service; then
      previous=active
    fi
    rm -f -- "$alert"
    trap 'echo "Exam activation failed. Rolling back restrictions." >&2; restore "$previous" || echo "Retry with exam-stop." >&2' ERR
    policy=$(mktemp "$conf/polkit.XXXXXX")
    policy_format=polkit
    policy_path=$polkit_rule
    if [[ $(dpkg-query -W -f='${Version}' polkitd) == 0.105-* ]]; then
      policy_format=polkit-pkla
      policy_path=$polkit_pkla
    fi
    /usr/bin/python3 -I "$lib/home.py" "$policy_format" "$exam_user" >"$policy"
    install -D -m 0644 "$policy" "$policy_path"
    rm -f -- "$policy"
    printf '%s\n' "$previous" >"$state/.active.next"
    sync -f "$state"
    install -D -m 0644 "$conf/usbguard.service.conf" "$dropin"
    # Persist boot configuration before committing the active marker.
    sync -f "$policy_path" "$dropin"
    mv -f -- "$state/.active.next" "$state/active"
    sync -f "$state"
    systemctl daemon-reload
    systemctl start exam-lockdown.service
    if [[ $previous == active ]]; then
      systemctl restart usbguard.service
    else
      systemctl start usbguard.service
    fi
    rules=$(timeout 5 usbguard list-rules)
    if ! grep -Eq '^[0-9]+: block with-interface .*08:\*:\*' <<<"$rules"; then
      echo 'USBGuard did not load the exam storage policy.' >&2
      false
    fi
    trap - ERR

    if [[ $wipe == yes ]]; then
      /usr/bin/python3 -I "$lib/home.py" check-mounts "$home"
      echo "Clearing files in $home and keeping its folders"
      # Keep the display session's conventional authentication files usable.
      (cd -- "$home" && find -P . -xdev -ignore_readdir_race -depth -mindepth 1 \
        ! -type d ! -path './.Xauthority' ! -path './.ICEauthority' -delete) ||
        die 'Wipe did not complete. Exam mode remains active.'
    fi
    runuser -u "$exam_user" -- /usr/bin/python3 -I "$lib/home.py" seed "$home" ||
      die 'Dataset copy failed. Exam mode remains active.'
    # Start the popup in an already-open desktop, before XDG autostart can run.
    runtime="/run/user/$exam_uid"
    if [[ -S $runtime/bus ]]; then
      # Replace a watcher already running from an older installation.
      pkill -TERM -u "$exam_uid" -f '^(bash|/usr/bin/bash|/bin/bash) /usr/local/libexec/exam-suite/desktop-alert$' ||
        true
      display_env=()
      for name in DISPLAY WAYLAND_DISPLAY XAUTHORITY; do
        if [[ -n ${!name:-} ]]; then
          display_env+=(--setenv="$name=${!name}")
        fi
      done
      runuser -u "$exam_user" -- env XDG_RUNTIME_DIR="$runtime" \
        DBUS_SESSION_BUS_ADDRESS="unix:path=$runtime/bus" \
        systemd-run --user --collect --unit="exam-usb-popup-$BASHPID" \
        "${display_env[@]}" "$lib/desktop-alert" \
        >/dev/null 2>&1 || true
    fi
    echo "Exam mode is on. CSV datasets are in $home."
    ;;
  *) die 'Invoke this program as exam-start, exam-stop, or exam-clear-alert.' ;;
esac
CONTROL
install -m 0700 "$stage/control" "$lib/control"
ln -sfn "$lib/control" /usr/local/bin/exam-start
ln -sfn "$lib/control" /usr/local/bin/exam-stop
ln -sfn "$lib/control" /usr/local/bin/exam-clear-alert

