Defaults!/usr/local/bin/exam-clear-alert !use_pty
ALL ALL=(root) NOPASSWD: NOSETENV: NOLOG_INPUT: NOLOG_OUTPUT: /usr/local/bin/exam-clear-alert --stdin
POPUP_SUDOERS
visudo -c -f "$stage/popup-sudoers"
