LOCKDOWN_UNIT
install -m 0644 "$stage/exam-lockdown.service" /etc/systemd/system/

cat >"$stage/usb-monitor" <<'MONITOR'
import os
from pathlib import Path
import sys

import pyudev


def has_storage_interface(descriptors):
    # Each cached USB descriptor begins with its length and type.
    offset = 0
    while offset + 2 <= len(descriptors):
        length, kind = descriptors[offset:offset + 2]
        if length < 2 or offset + length > len(descriptors):
            return False
        # Type 4 is an interface descriptor. Class 08 covers BOT and UAS.
        if kind == 4 and length >= 9 and descriptors[offset + 5] == 0x08:
            return True
        offset += length
    return False


def restore_storage():
    failed = False
    for device in pyudev.Context().list_devices(subsystem="usb", DEVTYPE="usb_device"):
        path = Path(device.sys_path)
        authorized = path / "authorized"
        try:
            if authorized.read_text().strip() != "0":
                continue
            if has_storage_interface((path / "descriptors").read_bytes()):
                authorized.write_text("1\n")
        except FileNotFoundError:
            if not path.exists():
                continue
            failed = True
            print(f"Missing USB authorization data for {device.sys_name}.", file=sys.stderr)
        except OSError as exc:
            if not path.exists():
                continue
            failed = True
            print(f"Could not restore USB storage on {device.sys_name}: {exc}", file=sys.stderr)
    return int(failed)


def watch_usb(flag):
    context = pyudev.Context()
    monitor = pyudev.Monitor.from_netlink(context, source="kernel")
    monitor.filter_by("usb", device_type="usb_device")
    monitor.start()
    alerted_ports = set()

    def inspect(device):
        path = device.sys_path
        if path in alerted_ports:
            return
        try:
            descriptors = (Path(path) / "descriptors").read_bytes()
        except OSError:
            return  # The USB device may have been unplugged already.
        if has_storage_interface(descriptors):
            # Flush the latch so an abrupt power loss cannot discard it.
            with flag.open("ab") as entry:
                os.fsync(entry.fileno())
            directory = os.open(flag.parent, os.O_RDONLY | os.O_DIRECTORY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
            alerted_ports.add(path)
            print(f"USB storage detected on {device.sys_name}. Exam alert set.", flush=True)

    # Subscribe before scanning so there is no gap for devices plugged in at startup.
    for device in context.list_devices(subsystem="usb"):
        if device.device_type == "usb_device":
            inspect(device)
    for device in iter(monitor.poll, None):
        if device.action == "add":
            inspect(device)
        elif device.action == "remove":
            alerted_ports.discard(device.sys_path)


if __name__ == "__main__":
    if sys.argv[1:] == ["--restore-storage"]:
        sys.exit(restore_storage())
    watch_usb(Path("/var/lib/exam-suite/usb-storage"))
MONITOR
install -m 0644 "$stage/usb-monitor" "$lib/usb-monitor"

cat >"$stage/exam-usb-alert.service" <<'ALERT_UNIT'
[Unit]
Description=Detect exam USB storage attempts at the USB bus
ConditionPathExists=/var/lib/exam-suite/active
PartOf=exam-lockdown.service
After=usbguard.service

[Service]
ExecStart=/usr/bin/python3 -I /usr/local/libexec/exam-suite/usb-monitor
Restart=on-failure
RestartSec=1
ALERT_UNIT
install -m 0644 "$stage/exam-usb-alert.service" /etc/systemd/system/

cat >"$stage/desktop-alert" <<'DESKTOP_ALERT'
#!/usr/bin/env bash
export PATH=/usr/bin:/bin
flag=/var/lib/exam-suite/usb-storage
popup=
sound=/usr/local/libexec/exam-suite/usb-alert.wav
sink=
saved_mute=
saved_volume=()
overamp_key=(org.gnome.desktop.sound allow-volume-above-100-percent)
saved_overamp=

restore_audio() {
  [[ -n $sink ]] || return 0
  timeout 2 pactl set-sink-volume "$sink" "${saved_volume[@]}" &&
    timeout 2 pactl set-sink-mute "$sink" "$saved_mute" || return 1
  sink=
}

restore_alarm_settings() {
  restore_audio || true
  if [[ -n $saved_overamp ]] &&
     timeout 2 gsettings set "${overamp_key[@]}" "$saved_overamp"; then
    saved_overamp=
  fi
}

play_alarm() {
  local output mute volume overamp
  output=$(timeout 2 pactl get-default-sink) || return
  [[ -n $output ]] || return 1
  if [[ $sink != "$output" ]]; then
    restore_audio || return
    mute=$(LC_ALL=C timeout 2 pactl get-sink-mute "$output") || return
    volume=$(LC_ALL=C timeout 2 pactl get-sink-volume "$output") || return
    mapfile -t saved_volume < <(
      grep -oE '[0-9]+[[:space:]]*/[[:space:]]*[0-9]+%' <<<"$volume" |
        sed -E 's/[[:space:]]*\/.*//'
    )
    (( ${#saved_volume[@]} )) || return 1
    case "$mute" in
      'Mute: yes') saved_mute=1 ;;
      'Mute: no') saved_mute=0 ;;
      *) return 1 ;;
    esac
    sink=$output
  fi
  if overamp=$(timeout 2 gsettings get "${overamp_key[@]}") &&
     [[ $overamp == true || $overamp == false ]]; then
    saved_overamp=${saved_overamp:-$overamp}
    if [[ $overamp == false ]]; then
      timeout 2 gsettings set "${overamp_key[@]}" true || true
    fi
  fi
  timeout 2 pactl set-sink-volume "$sink" 150% &&
    timeout 2 pactl set-sink-mute "$sink" 0 &&
    timeout 2 paplay --device="$sink" --volume=65536 "$sound"
}

close_popup() {
  if [[ -n $popup ]]; then
    kill "$popup" 2>/dev/null || true
    wait "$popup" 2>/dev/null || true
    popup=
  fi
}
trap 'exit 0' HUP INT TERM
trap 'close_popup; restore_alarm_settings >/dev/null 2>&1' EXIT
[[ -n ${DISPLAY:-}${WAYLAND_DISPLAY:-} ]] || exit 0
[[ -n ${XDG_RUNTIME_DIR:-} ]] || exit 0
if [[ -n ${DISPLAY:-} ]]; then
  export GDK_BACKEND=x11,wayland
fi
exec 8>"$XDG_RUNTIME_DIR/exam-usb-popup.lock"
flock -w 3 8 || exit 0
while true; do
  if [[ -f /var/lib/exam-suite/active && -e $flag ]]; then
    if command -v yad >/dev/null && { [[ -z $popup ]] || ! kill -0 "$popup" 2>/dev/null; }; then
      close_popup
      yad --entry --hide-text --image=dialog-warning --center --on-top \
        --sticky --undecorated --fixed --skip-taskbar --no-escape --width=500 \
        --title='Exam USB alert' --button='Unlock:0' \
        --text='USB storage was blocked. Enter the proctor password to dismiss this alert.' \
        > >(if IFS= read -r entered; then
              printf '%s\n' "$entered" |
                sudo -n /usr/local/bin/exam-clear-alert --stdin >/dev/null 2>&1
            fi) &
      popup=$!
    fi
    if play_alarm >/dev/null 2>&1; then
      continue
    fi
  else
    close_popup
    restore_alarm_settings >/dev/null 2>&1
  fi
  sleep 1
done
DESKTOP_ALERT
install -m 0755 "$stage/desktop-alert" "$lib/desktop-alert"
/usr/bin/python3 -I - "$stage/usb-alert.wav" <<'ALARM_SOUND'
import math
import struct
import sys
import wave

rate = 16000
with wave.open(sys.argv[1], "wb") as output:
    output.setparams((1, 2, rate, 0, "NONE", "not compressed"))
    samples = []
    for index in range(rate // 2):
        # Play a short tone followed by a pause, with a fade to avoid clicks.
        envelope = max(0, min(1, index / 160, (rate // 4 - index) / 160))
        samples.append(int(20000 * envelope * math.sin(2 * math.pi * 880 * index / rate)))
    output.writeframes(struct.pack(f"<{len(samples)}h", *samples))
ALARM_SOUND
install -m 0644 "$stage/usb-alert.wav" "$lib/usb-alert.wav"

cat >"$stage/exam-usb-alert.desktop" <<'AUTOSTART'
[Desktop Entry]
Type=Application
Name=Exam USB alert
Exec=/usr/local/libexec/exam-suite/desktop-alert
NoDisplay=true
AUTOSTART
install -D -m 0644 "$stage/exam-usb-alert.desktop" /etc/xdg/autostart/exam-usb-alert.desktop

# Remove known legacy files even when only part of the old installation remains.
if [[ $legacy_proctor == yes ]]; then
  rm -f -- "${legacy_files[@]}"
  for command in start stop; do
    path="/usr/local/bin/$command.sh"
    if [[ ! -e $path || $(readlink "$path") == "/usr/local/bin/exam-$command" ]] ||
       { [[ -f $path && ! -L $path ]] && grep -Eq 'exam-daemon|exam-monitor|exam_password|usbguard' "$path"; }; then
      ln -sfn "/usr/local/bin/exam-$command" "$path"
    elif [[ -f $path ]]; then
      die "Review the remaining legacy command at $path before using exam mode."
    fi
  done
  udevadm control --reload-rules
fi

if [[ -f $conf/usbguard-managed ]]; then
  for setting in /sys/bus/usb/devices/usb*/authorized_default; do
    [[ -f $setting ]] || continue
    printf '1\n' >"$setting" || [[ ! -e $setting ]]
  done
  /usr/bin/python3 -I "$lib/usb-monitor" --restore-storage
fi

systemctl daemon-reload
systemctl enable exam-lockdown.service
echo 'Setup complete. Run these commands from the same local session:'
echo '  sudo exam-start         Preserve existing files and add missing CSVs.'
echo '  sudo exam-start --wipe  Clear home files, keep folders, and copy the CSVs.'
echo '  sudo exam-stop             Prompt for the exam unlock password and restore access.'
